\begin{proof}

 Let $\rho\in{DRP}_n$ be as expressed in \eqref{2}, where $b(\rho)=r$ and $h(\rho)=p$. Moreover, let $w=\min(\mathop{\rm Dom}\nolimits \, \rho)$. Note that $p\leq w\leq n - p + 1$, from the proof of Lemma \ref{rev},   and for all $x_i \in \mathop{\rm Dom}\nolimits \, \rho$ and $a_j \in \mathop{\rm Im}\nolimits \, \rho$, we have $ a_j\leq x_i$. To count the number of $\rho\in{DRP}_n$, we first choose the domain elements. Now, since $w\in \mathop{\rm Dom}\nolimits \, \rho$, we can choose the remaining $r-1$ elements from $[n]\setminus\{1,\ldots,w\}$, i.e., in ${n - w \choose r - 1}$ ways. Next, we partition the $r$ elements in the domain into $p$  convex (modulo $\mathop{\rm Dom}\nolimits \, \rho$) blocks in ${r - 1 \choose p - 1}$ ways. Then, we can choose the $p$ images from the set $\{1,\ldots,w\}$  in ${w \choose p}$ ways. Finally, taking the sum of the product: ${n-w\choose r-1} {r-1\choose p-1} {w\choose p}$, from $w=p$ to $w=n-p+1$ produces
\begin{align*}  F(n,r,p)&=\sum_{w=p}^{n-p+1} {n-w\choose r-1} {r-1\choose p-1} {w\choose p}\\&=
{r-1\choose p-1}\sum_{w=p}^{n-p+1} {n-w\choose r-1}  {w\choose p}
\\&=
{r-1 \choose p-1} {n+1 \choose r+p}, \quad (\text{by Lemma \ref{id}})
\end{align*}
\noindent as postulated.

\end{proof}
\bigskip

\begin{corollary}\label{co}

The number of elements in ${DRP}_n$ of a fixed height $1\le p\le \lceil\frac{n}{2}\rceil$ is
\begin{equation}\label{coo} F(n,p)= \sum_{r=p}^{n-p+1}{r-1 \choose p-1} {n+1 \choose r+p}.\end{equation}
\end{corollary}
\begin{proof}
 We get the number by varying the width within the possible range which is $p\leq r\leq n-p+1$.
\end{proof}

We will now state the following lemma.
\begin{lemma} Let $F(n,p)$ be as in  \eqref{coo} and let $a_{n} = \sum\limits_{p=2}^{\lceil\frac{n}{2} \rceil} F(n, p)$. Then
\[
a_{n} =  \sum\limits_{p=2}^{\lceil\frac{n}{2} \rceil}  \sum_{r=p}^{n-p+1}  {r-1 \choose p-1} {n+1 \choose r+p}.
\]
\end{lemma}

At this point, we present the following result.

\begin{theorem} Let $s_{n}$ be as defined in \eqref{nums}. Then $|\mathcal{DORP}_{n}|=s_{n}+a_{n}$.
\end{theorem}
\begin{proof} Notice that, as in \eqref{qn2}, $\mathcal{DORP}_{n} = \mathcal{LS}_{n} \cup DRP_{n}$. However, elements of exactly height $1$ are both isotone and antitone maps, so  $$|\mathcal{LS}_{n} \cap DRP_{n}|=F(n,1).$$ \noindent Thus,  $$|\mathcal{DORP}_{n}| =|\mathcal{LS}_{n} \cup DRP_{n}|= |\mathcal{LS}_{n}|+| DRP_{n}|-| \mathcal{LS}_{n} \cap DRP_{n}|,$$ \noindent and therefore
\[|\mathcal{DORP}_{n}| =s_{n}+\sum\limits_{p=1}^{\lceil\frac{n}{2} \rceil} {F(n, p)}-F(n,1)=s_{n}+ F(n,1)+\sum\limits_{p=2}^{\lceil\frac{n}{2} \rceil} {F(n, p)}-F(n,1)=s_{n}+a_{n},\] as required.
\end{proof}

\begin{remark}
 It is  significant to highlight that the triangle of numbers $F(n,\, p)$ and the sequences $a_{n}$ and $s_{n}+a_{n}$ are not yet recorded in The Online Encyclopedia of Integer Sequences \cite{slone}.
\end{remark}

expanded_sketch:
Let $\rho\in DRP_n$ (as in \begin{equation}\label{2}
\rho = \begin{pmatrix} A_1 & \dots & A_p \\ a_p & \dots & a_1 \end{pmatrix},
\end{equation}
) with width $b(\rho)=r$ and height $h(\rho)=p$, and set $w=\min(\Dom\rho)$. \begin{lemma}\label{rev}
An element $\rho \in \mathcal{LS}_{n}$, as expressed in \eqref{1}, is reversible; that is, $\begin{pmatrix} A_1 & \dots & A_p \\ a_p & \dots & a_1 \end{pmatrix} \in \mathcal{DORP}_{n}$ if and only if $a_{p} \leq \min A_{1}$ and $1 \leq p \leq \lceil \frac{n}{2} \rceil$.
\end{lemma}
From the lemma above, $p\le w\le n-p+1$, and for all $x_i\in\Dom\rho$ and $a_j\in\Im\rho$ we have $a_j\le x_i$. Count such $\rho$ by fixing $w$:

1) Choose the domain: since $w\in\Dom\rho$, choose the remaining $r-1$ domain elements from $[n]\setminus\{1,\ldots,w\}$ in $\binom{n-w}{r-1}$ ways.

2) Partition the $r$ domain elements into $p$ convex (modulo $\Dom\rho$) blocks in $\binom{r-1}{p-1}$ ways.

3) Choose the $p$ images from $\{1,\ldots,w\}$ in $\binom{w}{p}$ ways.

Thus for fixed $w$ the count is $\binom{n-w}{r-1}\binom{r-1}{p-1}\binom{w}{p}$. Summing over $w=p,\ldots,n-p+1$ gives
\[
F(n,r,p)=\sum_{w=p}^{n-p+1} \binom{n-w}{r-1}\binom{r-1}{p-1}\binom{w}{p}
=\binom{r-1}{p-1}\sum_{w=p}^{n-p+1}\binom{n-w}{r-1}\binom{w}{p}
=\binom{r-1}{p-1}\binom{n+1}{r+p}\quad (\text{by }\begin{lemma}[\cite{44}, (3b), p.8]\label{id}
For all n \( m, n, k\in \mathbb{N} \), it follows that
\[
\sum_{j=k}^{m} \binom{j}{k} \binom{m+n-j}{n} = \binom{m+n+1}{n+k+1}.
\]
\end{lemma}
),
\]
which is the claimed formula.

ref_dict.thm:main:
\begin{theorem}\label{thm:main}
Let $D$ be a digraph with $\D=\Delta(D)$ sufficiently large, then $lla(D) \le \D+6 \sqrt{\D} \log^4\D $.
\end{theorem}

ref_dict.thm:Ordinary:
\begin{theorem}[{Lang and Postle~\cite[Theorem 4]{LP23}}]\label{thm:Ordinary}
		Let $G$ be an undirected graph with maximum degree $\D$ sufficiently large, then $lla(G)\leq \frac{\D}{2} + 3\sqrt{\D} \log^4\D $.
\end{theorem}

ref_dict.conj:LLAC:
\begin{conjecture}[List Linear Arboricity Conjecture]\label{conj:LLAC}
	For every undirected graph $G$ with maximum degree $\D$, $\lceil\frac{\D}{2}\rceil \le la(G)=lla(G) \le \lceil \frac{\D+1}{2}\rceil $.
\end{conjecture}

ref_dict.main B:
\begin{thm}\label{main B}
(i) For any rank 2 polystable non-unitary Higgs bundle, its isomonodromic deformation over $\mathcal T_g$ is never holomorphic.\\
(ii) For any rank 3 stable non-unitary Higgs bundle, its isomonodromic deformation over $\mathcal T_g$ is never holomorphic (for $g\geq 3$, this statement also holds for any rank 3 polystable non-unitary Higgs bundle).
\end{thm}

ref_dict.main A:
\begin{thm}\label{main A}
For a generic Higgs bundle in $\mathcal M_{\text{Dol}}(\mathcal X/\mathcal T_g)$, the isomonodromic deformation is not holomorphic along any direction in $\mathcal T_g$.
\end{thm}

post_theorem_intro_text:
We note that Theorem \ref{main A} corresponds to the claim in \cite[Theorem 3.3]{biswas}. Their proof relies heavily on \cite[Theorem 1.6]{Tos}. Here, we present a different and simpler proof utilizing the criterion (\ref{holcri}) alongside properties of the associated spectral curve.

We also establish non-existence results for low-rank non-unitary Higgs bundles, specifically for ranks 2 and 3.
\begin{thm}\label{main B}
(i) For any rank 2 polystable non-unitary Higgs bundle, its isomonodromic deformation over $\mathcal T_g$ is never holomorphic.\\
(ii) For any rank 3 stable non-unitary Higgs bundle, its isomonodromic deformation over $\mathcal T_g$ is never holomorphic (for $g\geq 3$, this statement also holds for any rank 3 polystable non-unitary Higgs bundle).
\end{thm}
Theorem \ref{main B} (i) was first stated in \cite[Theorem 3.4]{biswas}. However, by applying the criterion (\ref{holcri}), our approach offers a simpler proof. Indeed, we show that $\theta_\ast$ is always non-zero under the assumptions of Theorem \ref{main B}.

Motivated by Theorem \ref{main A} and Theorem \ref{main B}, we make the following conjecture:
\begin{conjx}For a non-nilpotent Higgs bundle $(E,\bar\partial,\theta)$ in $\mathcal M_{\text{Dol}}(\mathcal X/\mathcal T_g)$, its isomonodromic deformation fails to be holomorphic over $\mathcal T_g$.
\end{conjx}
\vspace{.5cm}
\noindent\textbf{Acknowledgements:}
We extend our thanks to H\'el\`ene Esnault and Moritz Kerz for drawing our attention to the work in \cite{biswas}. We also thank Xin L\"u for valuable discussions. We are grateful to Jinbang Yang for helpful discussions on Appendix B.

